#!/bin/bash
# Script to create spinal cord mask using sct_deepseg
# Usage: ./create_cord_mask.sh

# Save the directory of this script
SCRIPT_DIR="$( cd "$( dirname "${BASH_SOURCE[0]}" )" && pwd )"

cd $SCT_DIR/data/PAM50/template

# Create spinal cord segmentation using contrast-agnostic model (model_contrast_agnostic_20250123)
sct_deepseg spinalcord -i PAM50_t2.nii.gz -o PAM50_cord.nii.gz

# Remove JSON
rm PAM50_cord.json

# Symmetrize the segmentation
python3 "$SCRIPT_DIR/symmetrize_cord_segmentation.py" -i PAM50_cord.nii.gz --dtype uint8 --mode average -o PAM50_cord.nii.gz

# Add lumbo-sacral section from the original PAM50 mask, which was better segmented in that region.
# See: https://github.com/spinalcordtoolbox/PAM50/pull/49#issuecomment-3282508555
# Mask cord below z=104
sct_crop_image -i PAM50_cord.nii.gz -zmin 104 -zmax -1 -b 0 -o PAM50_cord_masked.nii.gz
